#include <stdio.h>
int main() {
    double a, b;
    char op;
    printf("Enter: num op num (op: + - * /): ");
    scanf("%lf %c %lf", &a, &op, &b);
    switch(op) {
        case '+': printf("%g\n", a+b); break;
        case '-': printf("%g\n", a-b); break;
        case '*': printf("%g\n", a*b); break;
        case '/': printf("%g\n", a/b); break;
        default: printf("Unknown op\n");
    }
}

