#!/bin/bash
read -p "Enter: num op num (op: + - * /): " a op b
case $op in
    +) echo "$a + $b" | bc;;
    -) echo "$a - $b" | bc;;
    \*) echo "$a * $b" | bc;;
    /) echo "scale=2; $a / $b" | bc;;
    *) echo "Unknown op";;
esac

